r=Path('~/cp-roles/classifier-B')
for cfg in ['plain','coroutines','constraints','session','tabling']:
 print('\\nCONFIG',cfg)
 for p in sorted((r/f'results/swi-prolog/{cfg}').glob('P0?/raw/*behaviour*.json')):
  x=json.loads(p.read_text());print('RUN',x['run']['instance'],Path(x['run']['program']['path']).name,'faults',str(x['harness_faults'])[:200])
  for s in x['stages']:
   for a in s['attempts']:
    print(' stage',s['stage'],'attempt',a['attempt'],'pose',a['posed']['how'], 'obs',repr(a['observe']['raw'][:160]))
    for c in a['computations']:
     print(' ',c['execution_state']['states'],'ans',[q['verbatim'][:800] for z in c['queries'] for q in z['answers']], 'susp',c['suspended']['items'],'end',[z['ended_by'] for z in c['queries']],'err',str(c['execution_state']['error_verbatim'])[:150], 'restart',c['steps']['restart_cost'])
PY"

