        'answers_verbatim':answers,
        'observe_raw':raw,
        'observe_bindings':obs['bindings'],
        'observe_method':obs['method'],
        'unknowns_representation':unknowns,
        'alternatives':at,
        'suspended':su,
        'steps':steps,
